//! Types shared by the spike's host and guest: the buffa messages from `proto/spike.proto`, and
//! the [`Buffa`] encoding that lets them cross an Extism call.

// Generated code carries its own lint allowances; the repo's clippy.toml nesting limit isn't one.
#[allow(warnings, clippy::all, reason = "generated by buffa-build")]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/protos.rs"));
}
pub use generated::*;

use extism_convert::{Error, FromBytesOwned, ToBytes};

/// Wraps a buffa message so Extism encodes it as protobuf on either side of a call.
///
/// `extism-convert` ships the same wrapper for prost (`Prost<T>`) but not for buffa, which is
/// what `nama-proto` uses. This is all a `nama-pdk` would need to add: ~20 lines, one generic.
#[derive(Debug)]
pub struct Buffa<T>(pub T);

impl<T: buffa::Message> ToBytes<'_> for Buffa<T> {
    type Bytes = Vec<u8>;

    fn to_bytes(&self) -> Result<Self::Bytes, Error> {
        Ok(self.0.try_encode_to_vec()?)
    }
}

impl<T: buffa::Message> FromBytesOwned for Buffa<T> {
    fn from_bytes_owned(data: &[u8]) -> Result<Self, Error> {
        Ok(Self(T::decode_from_slice(data)?))
    }
}
